#stage .hx-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================ THE STOPWATCH ============================ */
#stage .hx-top{
  height:82px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .hx-top.hot{ border-color:rgba(240,166,74,.5); box-shadow:0 0 34px rgba(240,166,74,.1); }
#stage .hx-top.ok{ border-color:rgba(63,185,80,.5); box-shadow:0 0 34px rgba(63,185,80,.1); }
#stage .hx-mark{
  width:48px; height:48px; border-radius:13px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42);
}
#stage .hx-url{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .hx-clock{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:7px; }
#stage .hx-clock b{
  color:#fff; font-family:var(--font-mono); font-size:34px; font-weight:800;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .hx-clock i{ color:var(--text-dim); font-size:21px; font-weight:700; font-style:normal; }
#stage .hx-clock.hot b{ color:var(--warn); }
#stage .hx-clock.ok b{ color:var(--success); }

/* ============================= SCENE STACK ============================= */
#stage .hx-body{ position:relative; flex:1; min-height:0; }
#stage .hx-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .hx-sc.on{ opacity:1; transform:none; }
#stage .hx-sc.whip{ animation:hx-whip .44s cubic-bezier(.19,1,.22,1); }
@keyframes hx-whip{
  0%{ transform:translateX(46px) scale(.984); opacity:0; }
  100%{ transform:none; opacity:1; }
}
#stage .hx-col{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* -------------------------------------------------------------- hero bar -- */
#stage .hx-hero{
  height:118px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
}
#stage .hx-hero-ic{
  width:58px; height:58px; border-radius:16px; flex-shrink:0; font-size:29px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .hx-hero-t{ display:flex; flex-direction:column; gap:7px; min-width:0; }
#stage .hx-hero-t b{ color:#fff; font-size:28px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .hx-hero-t i{ color:var(--text-dim); font-size:19px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .hx-hero-b{
  margin-left:auto; flex-shrink:0; padding:9px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(58,160,255,.45); background:rgba(58,160,255,.12); color:var(--accent-1);
  font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1px;
}
#stage .hx-hero-b.ok{ border-color:rgba(63,185,80,.55); background:rgba(63,185,80,.12); color:var(--success); }
#stage .hx-hero-b.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); color:var(--warn); }

/* ------------------------------------------------------------- the code -- */
#stage .hx-app{
  flex-shrink:0; border-radius:24px; overflow:hidden;
  background:var(--bg-panel); border:1.5px solid var(--border);
}
#stage .hx-app-h{
  height:72px; display:flex; align-items:center; gap:12px; padding:0 22px;
  background:rgba(38,52,78,.55); border-bottom:1.5px solid var(--border);
}
#stage .hx-app-ic{ font-size:26px; line-height:1; }
#stage .hx-app-h b{ color:#fff; font-size:24px; font-weight:800; letter-spacing:-.3px; }
#stage .hx-app-h i{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; font-style:normal; }
#stage .hx-code{ padding:26px 22px; display:flex; flex-direction:column; gap:14px; }
#stage .hx-line{
  color:var(--code-plain); font-family:var(--font-mono); font-size:25px; font-weight:600;
  line-height:1.45; word-break:break-word;
}
#stage .hx-line .k{ color:var(--code-keyword); }
#stage .hx-line .s{ color:var(--code-str); }
#stage .hx-line.c{ color:var(--code-comment); font-size:23px; }

/* ------------------------------------------------------------ the question -- */
#stage .hx-ask{
  flex:1; min-height:0; border-radius:24px; padding:24px 22px;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:30px;
  text-align:center;
  background:rgba(20,27,43,.55); border:1.5px solid var(--border);
}
#stage .hx-ask-q{ color:#fff; font-size:40px; font-weight:800; letter-spacing:-.7px; line-height:1.2; }
#stage .hx-ask-row{ display:flex; flex-wrap:wrap; gap:14px; justify-content:center; }
#stage .hx-chip{
  padding:14px 22px; border-radius:100px; white-space:nowrap;
  background:rgba(58,160,255,.1); border:1.5px solid rgba(58,160,255,.4);
  color:var(--text-primary); font-size:24px; font-weight:700;
}
#stage .hx-ask-x{ color:var(--text-dim); font-size:22px; font-weight:600; }

/* ---------------------------------------------------------- the metro map -- */
#stage .hx-map{
  flex:1; min-height:0; border-radius:24px; padding:16px;
  display:flex; flex-direction:column; justify-content:space-between; gap:10px;
  background:rgba(20,27,43,.55); border:1.5px solid var(--border);
}
#stage .hx-stop{
  position:relative; height:100px; flex-shrink:0;
  display:flex; align-items:center; gap:16px; padding:0 18px 0 76px; border-radius:20px;
  background:var(--bg-panel); border:1.5px solid var(--border);
  opacity:.45;
  transition:opacity .3s ease, border-color .3s ease, box-shadow .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
/* The line joining the stops, drawn through the gap between rows. */
#stage .hx-stop::before{
  content:''; position:absolute; left:32px; top:-10px; bottom:-10px; width:4px;
  background:var(--border); border-radius:2px;
}
#stage .hx-stop:first-child::before{ top:50%; }
#stage .hx-stop:last-child::before{ bottom:50%; }
#stage .hx-stop.done::before{ background:rgba(63,185,80,.5); }
#stage .hx-dot{
  position:absolute; left:22px; top:50%; margin-top:-12px; z-index:2;
  width:24px; height:24px; border-radius:50%;
  background:var(--bg-panel); border:4px solid var(--border);
  transition:background .3s ease, border-color .3s ease, box-shadow .3s ease;
}
#stage .hx-stop.done{ opacity:1; border-color:rgba(63,185,80,.4); }
#stage .hx-stop.done .hx-dot{ background:var(--success); border-color:var(--success); }
#stage .hx-stop.live{
  opacity:1; border-color:rgba(58,160,255,.65); transform:scale(1.012);
  box-shadow:0 0 0 1px rgba(58,160,255,.2), 0 0 46px rgba(58,160,255,.16);
}
#stage .hx-stop.live .hx-dot{
  background:var(--accent-1); border-color:var(--accent-1);
  box-shadow:0 0 0 6px rgba(58,160,255,.22);
  animation:msd-breathe 1.4s ease-in-out infinite;
}
#stage .hx-stop-ic{ font-size:32px; line-height:1; flex-shrink:0; }
#stage .hx-stop-t{ display:flex; flex-direction:column; gap:5px; min-width:0; }
#stage .hx-stop-t b{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .hx-stop-t i{ color:var(--text-dim); font-size:19px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .hx-stop-ms{
  margin-left:auto; flex-shrink:0; padding:8px 16px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(139,149,167,.22); background:rgba(139,149,167,.1); color:var(--text-dim);
  font-family:var(--font-mono); font-size:20px; font-weight:800; font-variant-numeric:tabular-nums;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .hx-stop.live .hx-stop-ms{ border-color:rgba(58,160,255,.5); background:rgba(58,160,255,.12); color:var(--accent-1); }
#stage .hx-stop.done .hx-stop-ms{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.12); color:var(--success); }
#stage .hx-stop.slow .hx-stop-ms{ border-color:rgba(240,166,74,.5); background:rgba(240,166,74,.14); color:var(--warn); }

/* ------------------------------------------------------------ the breakdown -- */
#stage .hx-bars{
  flex:1; min-height:0; border-radius:24px; padding:20px;
  display:flex; flex-direction:column; justify-content:space-evenly; gap:14px;
  background:rgba(20,27,43,.55); border:1.5px solid var(--border);
}
#stage .hx-bar{ display:flex; flex-direction:column; gap:12px; }
#stage .hx-bar-l{ color:var(--text-primary); font-size:24px; font-weight:700; }
#stage .hx-bar-t{ height:34px; border-radius:17px; background:rgba(139,149,167,.13); overflow:hidden; }
#stage .hx-bar-t i{
  display:block; height:100%; width:0; border-radius:17px;
  background:linear-gradient(90deg, var(--accent-2), var(--accent-1));
  transition:width .6s cubic-bezier(.4,0,.2,1);
}
#stage .hx-bar.warn .hx-bar-t i{ background:linear-gradient(90deg,#b8391f, var(--warn)); }
#stage .hx-bar.good .hx-bar-t i{ background:linear-gradient(90deg,#2b8a3e, var(--success)); }
#stage .hx-bar-v{
  position:absolute; opacity:0;
}
#stage .hx-bar{ position:relative; }
#stage .hx-bar .hx-bar-v{
  position:absolute; right:0; top:0; opacity:1;
  color:var(--text-dim); font-family:var(--font-mono); font-size:23px; font-weight:800;
  font-variant-numeric:tabular-nums;
}
#stage .hx-bar.warn .hx-bar-v{ color:var(--warn); }
#stage .hx-bar.good .hx-bar-v{ color:var(--success); }

/* -------------------------------------------------------- first vs second -- */
#stage .hx-vs{ flex:1; min-height:0; display:flex; gap:16px; }
#stage .hx-card{
  flex:1; min-width:0; border-radius:26px; padding:28px 20px;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:30px;
  text-align:center;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2)); border:1.5px solid var(--border);
}
#stage .hx-card.warn{ border-color:rgba(240,166,74,.5); box-shadow:inset 0 0 60px rgba(240,166,74,.06); }
#stage .hx-card.good{ border-color:rgba(63,185,80,.5); box-shadow:inset 0 0 60px rgba(63,185,80,.07); }
#stage .hx-card-h{ font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.3px; color:var(--text-dim); }
#stage .hx-card.warn .hx-card-h{ color:var(--warn); }
#stage .hx-card.good .hx-card-h{ color:var(--success); }
#stage .hx-card-v{
  color:#fff; font-family:var(--font-mono); font-size:66px; font-weight:900;
  letter-spacing:-2px; line-height:1; font-variant-numeric:tabular-nums;
}
#stage .hx-card-l{ display:flex; flex-direction:column; gap:18px; }
#stage .hx-card-l span{ color:var(--text-dim); font-size:23px; font-weight:600; line-height:1.3; white-space:nowrap; }

/* ------------------------------------------------------------ the one bug -- */
#stage .hx-split{ display:flex; gap:16px; height:100%; }
#stage .hx-scol{
  flex:1; min-width:0; border-radius:28px; padding:28px 20px;
  display:flex; flex-direction:column; align-items:center; gap:18px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2)); border:1.5px solid var(--border);
}
#stage .hx-scol.bad{ border-color:rgba(244,74,106,.5); box-shadow:inset 0 0 60px rgba(244,74,106,.07); }
#stage .hx-scol.good{ border-color:rgba(63,185,80,.5); box-shadow:inset 0 0 60px rgba(63,185,80,.07); }
#stage .hx-scol-h{
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:.6px;
  text-align:center; line-height:1.3;
}
#stage .hx-scol.bad .hx-scol-h{ color:var(--danger); }
#stage .hx-scol.good .hx-scol-h{ color:var(--success); }
#stage .hx-scol-ic{ font-size:56px; line-height:1; }
#stage .hx-scol-list{ flex:1; width:100%; display:flex; flex-direction:column; justify-content:space-evenly; gap:16px; }
#stage .hx-row{ color:var(--text-primary); font-size:23px; font-weight:600; text-align:center; line-height:1.3; }
#stage .hx-row b{ color:#fff; font-weight:800; }
#stage .hx-scol-x{
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700;
  text-align:center; line-height:1.35;
}
#stage .hx-scol-x.ok{ color:var(--success); }

/* -------------------------------------------------------------- the payoff -- */
#stage .hx-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:22px;
  text-align:center;
}
#stage .hx-badge{
  width:120px; height:120px; border-radius:34px; font-size:56px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338);
  border:1.5px solid rgba(58,160,255,.5); box-shadow:0 0 60px rgba(58,160,255,.2);
}
#stage .hx-badge-l{ color:var(--accent-1); font-family:var(--font-mono); font-size:20px; font-weight:800; letter-spacing:3.5px; }
#stage .hx-fin-h{ color:#fff; font-size:62px; font-weight:900; line-height:1.14; letter-spacing:-1.8px; }
#stage .hx-fin-h em{ font-style:normal; color:var(--accent-1); }
#stage .hx-fin-row{ display:flex; flex-wrap:wrap; gap:12px; justify-content:center; max-width:900px; }
#stage .hx-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(58,160,255,.1); border:1.5px solid rgba(58,160,255,.42);
  color:var(--text-primary); font-size:21px; font-weight:700;
}
#stage .hx-save{
  margin-top:6px; padding:15px 26px; border-radius:18px; max-width:860px;
  background:rgba(240,166,74,.1); border:1.5px solid rgba(240,166,74,.42);
  color:var(--warn); font-size:22px; font-weight:700; line-height:1.35;
  transition:transform .3s cubic-bezier(.22,1,.36,1), box-shadow .3s ease;
}
#stage .hx-save.ping{ transform:scale(1.035); box-shadow:0 0 44px rgba(240,166,74,.24); }

/* --------------------------------------------------------- bottom strip -- */
#stage .hx-strip{
  height:100px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.72); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .hx-strip.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.09); }
#stage .hx-strip.warn{ border-color:rgba(240,166,74,.5); background:rgba(240,166,74,.09); }
#stage .hx-strip.good{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.09); }
#stage .hx-strip b{
  flex-shrink:0; padding:9px 16px; border-radius:11px;
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:1.4px;
  color:var(--text-dim); background:rgba(139,149,167,.12); border:1.5px solid rgba(139,149,167,.22);
  transition:color .3s ease, background .3s ease, border-color .3s ease;
}
#stage .hx-strip.bad b{ color:var(--danger); background:rgba(244,74,106,.16); border-color:rgba(244,74,106,.5); }
#stage .hx-strip.warn b{ color:var(--warn); background:rgba(240,166,74,.16); border-color:rgba(240,166,74,.5); }
#stage .hx-strip.good b{ color:var(--success); background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.5); }
#stage .hx-strip span{ color:var(--text-primary); font-size:24px; font-weight:600; line-height:1.3; }

