var HX = window.__HX || (window.__HX = {});

/* The seven stops, in order: label for the strip, and the cost in ms. */
HX.COST = [30, 70, 15, 5, 10, 20, 10];

/** Ramps the stopwatch from one total to another. */
HX.clock = function(from, to, ms, tone){
  var el = MSD.q('#hx-clock-n'); if(!el) return;
  MSD.cls('#hx-clock', 'hot', tone === 'hot');
  MSD.cls('#hx-clock', 'ok', tone === 'ok');
  MSD.cls('#hx-top', 'hot', tone === 'hot');
  MSD.cls('#hx-top', 'ok', tone === 'ok');
  var steps = Math.max(1, Math.round(ms / 40)), i = 0;
  var id = MSD.every(40, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = String(Math.round(from + (to - from) * p));
    if(p >= 1) clearInterval(id);
  });
};

HX.scene = function(id, whip){
  MSD.cls('.hx-sc', 'on', false);
  MSD.cls('#hx-sc-' + id, 'on', true);
  MSD.cls('#hx-sc-' + id, 'whip', false);
  if(whip) MSD.after(20, function(){ MSD.cls('#hx-sc-' + id, 'whip', true); MSD.sfx.swipe(); });
};

HX.strip = function(id, label, text, tone){
  MSD.cls(id, 'bad', tone === 'bad');
  MSD.cls(id, 'warn', tone === 'warn');
  MSD.cls(id, 'good', tone === 'good');
  MSD.q(id + '-l').textContent = label;
  MSD.q(id + '-t').textContent = text;
};

/**
 * Paints the metro map. "live" is the stop being explained; every stop
 * before it is done and carries its cost, every stop after is dimmed.
 * live === 0 lights the whole line.
 */
HX.map = function(live){
  for(var i = 1; i <= 7; i++){
    var done = live === 0 || i < live;
    MSD.cls('#hx-stop-' + i, 'live', i === live);
    MSD.cls('#hx-stop-' + i, 'done', done);
    MSD.q('#hx-stop-' + i + '-ms').textContent =
      (done || i === live) ? (HX.COST[i - 1] + ' ms') : '—';
  }
  // The handshake is the one stop worth flagging as expensive.
  MSD.cls('#hx-stop-2', 'slow', live === 0 || live > 2);
};

HX.scene('code');
MSD.q('#hx-url').textContent = 'GET api.contoso.com/orders';
HX.clock(0, 0, 40, '');
MSD.hide('.hx-chip');
MSD.hide('#hx-line-2');
HX.strip('#hx-strip', 'ONE LINE', 'You write one line. Your request takes a seven-stop trip.', '');

MSD.after(500, function(){ MSD.punch('#hx-app', 1); MSD.sfx.lock(); });
MSD.after(1500, function(){ MSD.show('#hx-line-2'); MSD.sfx.blip(2); });
MSD.after(2400, function(){ MSD.show('.hx-chip', 220); });
MSD.after(3800, function(){
  HX.strip('#hx-strip', 'LET US WATCH', 'Follow one request all the way to Azure and back.', 'good');
  MSD.punch('#hx-strip', 4);
});

var HX = window.__HX;

HX.scene('map', true);
HX.map(1);
HX.clock(0, 30, 900, 'hot');
HX.strip('#hx-strip-2', 'STOP 1', 'Your app has a name. The internet only understands numbers.', '');

MSD.after(600, function(){ MSD.punch('#hx-stop-1', 1); MSD.sfx.blip(1); });
MSD.after(1800, function(){
  MSD.q('#hx-url').textContent = 'api.contoso.com → 20.51.4.117';
  MSD.sfx.data(1);
});
MSD.after(3000, function(){
  HX.strip('#hx-strip-2', 'GOOD NEWS', 'The answer is cached, so you only pay this on the first call.', 'good');
  MSD.punch('#hx-strip-2', 3);
});

var HX = window.__HX;

HX.scene('map');
HX.map(2);
HX.clock(30, 100, 1400, 'hot');
MSD.q('#hx-url').textContent = 'TLS 1.3 · verifying certificate';
HX.strip('#hx-strip-2', 'STOP 2', 'Nice to meet you. Here is my certificate. Now we can talk.', '');

MSD.after(600, function(){ MSD.punch('#hx-stop-2', 2); MSD.sfx.blip(2); });
MSD.after(2000, function(){
  MSD.cls('#hx-stop-2', 'slow', true);
  MSD.punch('#hx-stop-2-ms', 3);
  MSD.sfx.thud();
});
MSD.after(3200, function(){
  HX.strip('#hx-strip-2', 'THE BIG ONE', 'This is the most expensive stop on the whole trip — and you have sent nothing yet.', 'warn');
  MSD.punch('#hx-strip-2', 4);
});

var HX = window.__HX;

HX.scene('map');
HX.map(3);
HX.clock(100, 115, 600, 'hot');
MSD.q('#hx-url').textContent = 'POP: Chennai edge · WAF: clean';
HX.strip('#hx-strip-2', 'STOP 3', 'You reach Azure at the closest city, not at the datacentre.', '');

MSD.after(600, function(){ MSD.punch('#hx-stop-3', 3); MSD.sfx.blip(3); });
MSD.after(2400, function(){
  HX.strip('#hx-strip-2', 'FREE SECURITY', 'Bad requests are stopped here, before they ever reach your code.', 'good');
  MSD.punch('#hx-strip-2', 4);
});

var HX = window.__HX;

HX.scene('map');
HX.map(4);
